<?php require_once __DIR__.'/config/config.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST'){redirect('index.php');}verify_csrf();$pid=(int)($_POST['post_id']??0);$reaction=$_POST['reaction']??'';if(!array_key_exists($reaction,reaction_options())){flash('Invalid reaction.','error');redirect('index.php');}$s=$conn->prepare('SELECT user_id FROM posts WHERE id=?');$s->bind_param('i',$pid);$s->execute();$post=$s->get_result()->fetch_assoc();if(!$post){flash('Post not found.','error');redirect('index.php');}$uid=current_user_id();$s=$conn->prepare('SELECT reaction FROM reactions WHERE post_id=? AND user_id=?');$s->bind_param('ii',$pid,$uid);$s->execute();$old=$s->get_result()->fetch_assoc();if($old&&$old['reaction']===$reaction){$s=$conn->prepare('DELETE FROM reactions WHERE post_id=? AND user_id=?');$s->bind_param('ii',$pid,$uid);$s->execute();}else{$s=$conn->prepare('INSERT INTO reactions(post_id,user_id,reaction) VALUES(?,?,?) ON DUPLICATE KEY UPDATE reaction=VALUES(reaction)');$s->bind_param('iis',$pid,$uid,$reaction);$s->execute();if(!$old)notify_user($conn,(int)$post['user_id'],$uid,'reaction',$pid);} $back=$_SERVER['HTTP_REFERER']??BASE_URL.'/index.php';header('Location: '.$back.'#post-'.$pid);exit;?>